function DecomposeAndCoordinate(problem, budget)
    partitions <- InitialPartition(problem)                          // spatial clusters, job blocks, or demand groups
    lambda <- InitializeDuals(partitions)                            // multipliers for capacity/interfaces/precedence
    subsolutions <- {}
    while not StoppingCriterion(budget, lambda, subsolutions) do
        // solve parts in parallel using best available exact/heuristic solver per subproblem type
        for p in partitions in Parallel do
            subsolutions[p] <- SolveSubproblem(p, problem, lambda[p]) // returns local solution + interface metrics
        end for
        // form compact boundary/interaction model that captures crossings, loads, and machine handoffs
        boundaryProblem <- BuildBoundaryModel(subsolutions, problem)
        boundarySolution <- SolveBoundary(boundaryProblem)            // small global/bridge optimization
        // coordinate via Lagrangian-style updates and optionally fix good interfaces
        lambda <- UpdateDuals(lambda, subsolutions, boundarySolution) // subgradient/dual-ascent with step control
        // adaptive refinement of decomposition: split overloaded partitions, merge weakly-coupled ones
        partitions <- RefinePartitions(partitions, subsolutions, boundarySolution)
        // optionally inject targeted exact solves on critical partitions to tighten bounds
        SelectivePolish(subsolutions, partitions, problem)
    end while
    return AssembleGlobalSolution(subsolutions, boundarySolution)     // decode tour(s), routes, or job sequence
end function

